typedef float rational_t;

class stringx
{
  char *chars;
  int length;
public:
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const stringx &);
};

class animation_interface
{
public:
  struct anim_info
  {
    rational_t percent;
    stringx anim;
    int damage;
    rational_t recover_time;
    rational_t recover_var;
    int flags;

    anim_info();
    anim_info(rational_t, const stringx &, int, rational_t, rational_t, int);
  };
};

extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);
inline void *operator new(unsigned int, void *p) { return p; }

template<class T>
class my_allocator
{
public:
  static T *allocate(unsigned int n)
  {
    return n ? (T *)arch_malloc(n * sizeof(T), __FILE__, 0) : 0;
  }
  static void deallocate(T *p, unsigned int)
  {
    if (p) arch_free(p);
  }
};

template<class T1, class T2>
inline void construct(T1 *p, const T2 &value)
{
  if (p) new ((void *)p) T1(value);
}

template<class T>
inline T *copy_backward(T *first, T *last, T *result)
{
  while (first != last) *--result = *--last;
  return result;
}

template<class T>
inline T *uninitialized_copy(T *first, T *last, T *result)
{
  T *cur = result;
  for (; first != last; ++first, ++cur) construct(cur, *first);
  return cur;
}

template<class T>
inline void destroy(T *first, T *last)
{
  for (; first != last; ++first) first->~T();
}

template<class T, class Alloc>
class vector
{
protected:
  T *start_;
  T *finish_;
  T *end_of_storage_;
  T *allocate(unsigned int n) { return Alloc::allocate(n); }
  void deallocate(T *p, unsigned int n) { Alloc::deallocate(p, n); }
public:
  typedef T *iterator;
  typedef unsigned int size_type;
  iterator begin() { return start_; }
  iterator end() { return finish_; }
  size_type size() const { return finish_ - start_; }
  void _M_insert_aux(iterator position, const T &x);
};

template<class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator position, const T &x)
{
  if (finish_ != end_of_storage_)
  {
    construct(finish_, *(finish_ - 1));
    ++finish_;
    T x_copy = x;
    copy_backward(position, finish_ - 2, finish_ - 1);
    *position = x_copy;
  }
  else
  {
    const size_type old_size = size();
    const size_type len = old_size != 0 ? 2 * old_size : 1;
    iterator new_start = allocate(len);
    iterator new_finish = new_start;
    new_finish = uninitialized_copy(start_, position, new_start);
    construct(new_finish, x);
    ++new_finish;
    new_finish = uninitialized_copy(position, finish_, new_finish);
    destroy(begin(), end());
    deallocate(start_, end_of_storage_ - start_);
    start_ = new_start;
    finish_ = new_finish;
    end_of_storage_ = new_start + len;
  }
}

template void vector<animation_interface::anim_info, my_allocator<animation_interface::anim_info> >::_M_insert_aux(
  animation_interface::anim_info *, const animation_interface::anim_info &);
